node --check app.js && git diff --check && python3 - <<'PY'
from pathlib import Path
import re
css=Path('styles.css').read_text()
# Lightweight structural check for balanced CSS braces while respecting comments and strings.
s=re.sub(r'/\*.*?\*/', '', css, flags=re.S)
s=re.sub(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'', '', s)
level=0
for ch in s:
    if ch=='{': level+=1
    elif ch=='}':
        level-=1
        if level<0: raise SystemExit('CSS has an unmatched closing brace')
if level: raise SystemExit(f'CSS has {level} unmatched opening brace(s)')
html=Path('index.html').read_text()
if 'helpButton' in html or 'help-button' in html: raise SystemExit('Help button still present in HTML')
if 'helpButton' in Path('app.js').read_text(): raise SystemExit('Help handler still present')
print('Syntax and structural checks passed')
PY
