308: .spark-b{animation-delay:-1.6s}
309: .art-orbit{animation:orbit-shimmer 5s ease-in-out infinite alternate}
310: .orbit-two{animation-delay:-2.5s}
311: .art-orb{animation:orb-drift 3.8s ease-in-out infinite}
