import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page = await ctx.newPage()
  page.on('pageerror', e => console.error('pageerror:', e.message))
  page.on('console', m => { if (m.type() === 'error') console.error('console:', m.text()) })
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  await page.click('[data-tool="watermark"]')
  await page.setInputFiles('#fileInput', '/tmp/opencode/assets/sample.pdf')
  await page.fill('#watermarkText', 'DRAF')
  const p = page.waitForEvent('download', { timeout: 20000 }).then(d => { console.log('DOWNLOAD OK'); return d })
  await page.click('#modalAction')
  await page.waitForTimeout(3000)
  console.log('modalError text:', await page.locator('#modalError').textContent().catch(() => 'n/a'))
  console.log('modalError visible:', await page.locator('#modalError').evaluate(el => el.classList.contains('show')))
  const result = await Promise.race([p.catch(e => 'no download: ' + e.message.split('\n')[0]), page.waitForTimeout(21000).then(() => 'timeout')])
  console.log('result:', result)
} finally { await browser.close() }

