import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage()
  page.on('pageerror', e => console.error('pageerror:', e.message))
  page.on('console', m => console.log('console[' + m.type() + ']:', m.text()))
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  await page.click('[data-tool="edit"]')
  await page.evaluate(() => {
    window._log = []
    window._err = null
    const logRender = renderEditorPage
    renderEditorPage = function (...a) { window._log.push('renderEditorPage dipanggil'); const p = logRender.apply(this, a); p.then(() => window._log.push('renderEditorPage selesai, canvas=' + document.getElementById('editorPageCanvas').width)).catch(e => { window._err = 'render: ' + (e && e.stack || e) }); return p }
    const logDown = onEditorStagePointerDown
    onEditorStagePointerDown = function (e) { try { window._log.push('pointerDown dipanggil tool=' + editor.tool + ' doc=' + !!editor.doc); return logDown.call(this, e) } catch (err) { window._err = 'down: ' + (err && err.stack || err); throw err } }
  })
  await page.setInputFiles('#fileInput', '/tmp/opencode/assets/sample.pdf')
  await page.waitForTimeout(3000)
  const box = await page.locator('#editorStage').boundingBox()
  await page.mouse.click(box.x + box.width * .12, box.y + box.height * .18)
  await page.waitForTimeout(1200)
  console.log('log:', JSON.stringify(await page.evaluate(() => window._log), null, 1))
  console.log('err:', await page.evaluate(() => window._err))
  console.log('items:', JSON.stringify(await page.evaluate(() => JSON.parse(JSON.stringify(editor.items)))))
  console.log('canvas:', JSON.stringify(await page.evaluate(() => { const c = document.getElementById('editorPageCanvas'); return { w: c.width, h: c.height } })))
} finally { await browser.close() }

