import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage()
  const errs = []
  page.on('pageerror', e => errs.push(e.message))
  page.on('console', m => { if (m.type() === 'error') errs.push('console: ' + m.text()) })
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  // OCR mode PDF bisa dicari, sambil mengecek progress bar
  await page.click('[data-tool="ocr"]')
  await page.setInputFiles('#fileInput', '/tmp/opencode/assets/sample.pdf')
  await page.click('.option-chip:has(input[value="pdf"])')
  const dl = page.waitForEvent('download', { timeout: 240000 })
  await page.click('#modalAction')
  await page.waitForTimeout(900)
  const mid = await page.evaluate(() => ({
    barShow: document.getElementById('modalProgress').classList.contains('show'),
    indet: document.getElementById('modalProgressFill').classList.contains('indeterminate'),
    width: parseFloat(document.getElementById('modalProgressFill').style.width),
    anim: getComputedStyle(document.getElementById('modalProgressFill')).animationName,
    bg: getComputedStyle(document.getElementById('modalProgressFill')).backgroundImage.includes('linear-gradient'),
    btnLoading: document.getElementById('modalAction').classList.contains('loading'),
    spinner: !!document.querySelector('#modalAction .button-spinner'),
    label: document.getElementById('modalProgressLabel').textContent
  }))
  console.log('mid-OCR state:', JSON.stringify(mid))
  await page.screenshot({ path: '/tmp/opencode/paperly-capture/progress-bar.jpg', quality: 60, type: 'jpeg' })
  await (await dl).saveAs('/tmp/opencode/assets/out-ocr-search.pdf')
  await page.waitForTimeout(500)
  const b64 = readFileSync('/tmp/opencode/assets/out-ocr-search.pdf').toString('base64')
  const text = await page.evaluate(async b64 => {
    const bin = atob(b64), bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
    const d = await pdfjsLib.getDocument({ data: bytes.slice() }).promise
    const out = []
    for (let p = 1; p <= d.numPages; p++) out.push((await (await d.getPage(p)).getTextContent()).items.map(i => i.str).join(' '))
    return { pages: d.numPages, text: out.join(' | ') }
  }, b64)
  console.log('hasil OCR searchable:', JSON.stringify(text).slice(0, 300))
  console.log(errs.length ? 'ERRORS: ' + errs.join('; ') : 'tanpa error')
} finally { await browser.close() }

