await (await dl).saveAs(A + '/out-ocr-search.pdf')
const b64search = fs.readFileSync(A + '/out-ocr-search.pdf').toString('base64')
const search = await page.evaluate(async b64 => {
  const bin = atob(b64), bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  const d = await pdfjsLib.getDocument({ data: bytes.slice() }).promise
  const parts = []
  for (let p = 1; p <= d.numPages; p++) parts.push((await (await d.getPage(p)).getTextContent()).items.map(i => i.str).join(' '))
  return { pages: d.numPages, text: parts.join(' | ') }
}, b64search)
ok('OCR searchable: 3 halaman', search.pages === 3)
ok('OCR searchable: lapisan teks berisi "Paperly"', /paperly/i.test(search.text))
await page.keyboard.press('Escape')

/* ===== BATCH: kompres 2 file → ZIP ===== */
const fflate = require(process.cwd() + '/vendor/fflate.js')
await page.click('[data-tool="compress"]')
await page.setInputFiles('#fileInput', [PDF, PDF])
ok('batch: dua file terdaftar', (await page.locator('#fileRows .file-row').count()) === 2)
dl = page.waitForEvent('download', { timeout: 60000 })
await page.click('#modalAction')
await (await dl).saveAs(A + '/out-batch-compress.zip')
ok('batch kompres → ZIP', fs.readFileSync(A + '/out-batch-compress.zip').slice(0, 2).toString() === 'PK')
const zip1 = fflate.unzipSync(new Uint8Array(fs.readFileSync(A + '/out-batch-compress.zip')))
ok('batch kompres: 2 PDF di dalam ZIP', Object.keys(zip1).length === 2 && Object.values(zip1).every(b => b.slice(0, 5).toString() === '%PDF-'))
await page.keyboard.press('Escape')

/* ===== BATCH: tanda air 2 file → ZIP ===== */
await page.click('[data-tool="watermark"]')
await page.setInputFiles('#fileInput', [PDF, PDF])
await page.fill('#watermarkText', 'DRAF')
dl = page.waitForEvent('download')
await page.click('#modalAction')
await (await dl).saveAs(A + '/out-batch-watermark.zip')
