ok('batch tanda air: 2 PDF hasil', Object.keys(zip2).length === 2 && Object.values(zip2).every(b => b.slice(0, 5).toString() === '%PDF-'))
await page.keyboard.press('Escape')

/* ===== BATCH: putar 2 file → ZIP, rotasi tervalidasi ===== */
await page.click('[data-tool="rotate"]')
await page.setInputFiles('#fileInput', [PDF, PDF])
dl = page.waitForEvent('download')
await page.click('#modalAction')
await (await dl).saveAs(A + '/out-batch-rotate.zip')
const zip3 = fflate.unzipSync(new Uint8Array(fs.readFileSync(A + '/out-batch-rotate.zip')))
const rotOk = await Promise.all(Object.values(zip3).map(async b => (await Cantoo.PDFDocument.load(b)).getPages()[0].getRotation().angle === 90))
ok('batch putar: 2 PDF masing-masing 90°', Object.keys(zip3).length === 2 && rotOk.every(Boolean))
await page.keyboard.press('Escape')

