const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage()
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  await page.click('[data-tool="ocr"]')
  await page.setInputFiles('#fileInput', '/tmp/opencode/assets/sample.pdf')
  await page.click('#modalAction')
  await page.waitForFunction(() => parseFloat(document.getElementById('modalProgressFill').style.width) > 10, { timeout: 60000 }).catch(() => {})
  await page.waitForTimeout(300)
  await page.locator('.tool-modal').screenshot({ path: '/tmp/opencode/paperly-capture/progress-modal.jpg', quality: 70, type: 'jpeg' })
  console.log('width:', await page.evaluate(() => document.getElementById('modalProgressFill').style.width))
  console.log('label:', await page.evaluate(() => document.getElementById('modalProgressLabel').textContent))
} finally { await browser.close() }

