async function exportDocToPdf(report){if(docIsEmpty())throw Error('Dokumen masih kosong. Tulis sesuatu terlebih dahulu.');const doc=await PDFDocument.create();const fontCache={};const famMap={sans:{r:StandardFonts.Helvetica,b:StandardFonts.HelveticaBold,i:StandardFonts.HelveticaOblique,bi:StandardFonts.HelveticaBoldOblique},serif:{r:StandardFonts.TimesRoman,b:StandardFonts.TimesRomanBold,i:StandardFonts.TimesRomanItalic,bi:StandardFonts.TimesRomanBoldItalic},mono:{r:StandardFonts.Courier,b:StandardFonts.CourierBold,i:StandardFonts.CourierOblique,bi:StandardFonts.CourierBoldOblique}};
