/* ===== Pembuat PDF dari halaman kosong ===== */
.doc-builder{margin-top:14px;display:flex;flex-direction:column;gap:10px}
.doc-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:5px;padding:8px;border:1px solid #e7eaf1;border-radius:10px;background:#fafbfe}
.doc-toolbar .editor-btn{padding:6px 9px;font-size:11px;min-width:30px}
.doc-toolbar-sep{width:1px;height:22px;background:#e3e7ef;margin:0 2px}
.doc-select{height:30px;padding:0 8px;border:1px solid #e5e9f0;border-radius:7px;background:#fff;color:#495771;font:11px 'DM Sans',sans-serif;outline:none;cursor:pointer}
#docColor{width:30px;height:30px;padding:2px;border:1px solid #e5e9f0;border-radius:7px;background:#fff;cursor:pointer}
.doc-pages{max-height:52vh;overflow-y:auto;padding:14px;border:1px solid #e9edf4;border-radius:12px;background:linear-gradient(140deg,#f6f8fd,#f4f9f7)}
.doc-page{min-height:340px;padding:38px 42px;background:#fff;border:1px solid #e8ecf3;border-radius:6px;box-shadow:0 4px 14px rgba(45,58,90,.06);outline:none;color:#1c2940;font:400 14px/1.7 'DM Sans',sans-serif;caret-color:#5676e8}
.doc-page+.doc-page{margin-top:14px;position:relative}
.doc-page:focus{border-color:#a9b4ec}
.doc-page h1{font:700 24px Manrope,sans-serif;margin:0 0 12px;color:#1c2a43}
.doc-page h2{font:700 18px Manrope,sans-serif;margin:10px 0 8px;color:#26344d}
.doc-page h3,.doc-page h4{font:700 15px Manrope,sans-serif;margin:8px 0 6px;color:#2e3c55}
.doc-page p{margin:0 0 8px}
.doc-page ul,.doc-page ol{margin:4px 0 10px;padding-left:22px}
.doc-page img{max-width:100%;border-radius:4px;display:block;margin:6px auto}
.doc-page:empty::before{content:'Mulai menulis…';color:#b7c0d0;pointer-events:none}
@media(prefers-reduced-motion:reduce){.doc-page,.doc-pages{scroll-behavior:auto}}

