{id:'kelola',title:'Kelola Halaman',description:'Susun, pisahkan, dan rapikan halaman dokumen Anda.',ids:['split','merge','extract','rotate','number']},
{id:'optimal',title:'Optimasi & Keamanan',description:'Kecilkan ukuran file dan lindungi dokumen.',ids:['compress','protect','unlock','watermark']},
{id:'konversi',title:'Ubah Format',description:'Pindahkan PDF ke format lain dan sebaliknya.',ids:['toWord','toPpt','ocr','images']}
];
function toolCard(t){return `<button class="tool-card" data-tool="${t.id}"><span class="tool-top"><span class="tool-icon ${t.color}">${icon(t.icon)}</span><span class="tool-arrow">↗</span></span>${t.tag?`<span class="tool-tag ${t.tag==='BARU'?'new':''}">${t.tag}</span>`:''}<h3>${t.title}</h3><p>${t.description}</p></button>`}
