          const out=await PDFLib.PDFDocument.load(u.slice());
          const xo=[];
          for(let i=0;i<out.getPageCount();i++){const e=out.getPage(i).node.normalizedEntries().XObject;xo.push(e?Object.keys(e).length:0)}
          pdf.destroy();
          done({pages:pdf.numPages,texts,xo});
        })().catch(e=>done({error:String(e)}))""",[b64])
        print(path.split('/')[-1], json.dumps(r))
