import json, urllib.request, time, base64
BASE='http://127.0.0.1:9515'
def req(method,path,data=None):
    body=None if data is None else json.dumps(data).encode()
    r=urllib.request.Request(BASE+path,data=body,headers={'Content-Type':'application/json'},method=method)
    with urllib.request.urlopen(r,timeout=90) as x: return json.loads(x.read() or b'{}')
opts={'capabilities':{'alwaysMatch':{'browserName':'chrome','goog:chromeOptions':{'args':['--headless=new','--no-sandbox','--disable-dev-shm-usage','--window-size=1240,860','--hide-scrollbars','--force-device-scale-factor=1']}}}}
sid=req('POST','/session',opts)['value']['sessionId']; root='/session/'+sid
def call(method,path,data=None):
    v=req(method,root+path,data); return v.get('value')
def js(script,args=[]): return call('POST','/execute/sync',{'script':script,'args':args})
def asyncjs(script,args=[]): return call('POST','/execute/async',{'script':script,'args':args})
def waitjs(expr,timeout=40):
    end=time.time()+timeout
    while time.time()<end:
        if js('return '+expr): return True
        time.sleep(.2)
    raise TimeoutError(expr)
try:
    call('POST','/url',{'url':'http://127.0.0.1:8765/'})
    waitjs("document.readyState==='complete'")
    # open redact with the secret pdf, draw a box, wait for render
    js("document.querySelector(`[data-tool='redact']`).click()")
    b64=base64.b64encode(open('/tmp/opencode/secret.pdf','rb').read()).decode()
    js("const b=atob(arguments[0]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);const dt=new DataTransfer();dt.items.add(new File([u],'secret.pdf',{type:'application/pdf'}));const el=document.getElementById('fileInput');el.files=dt.files;el.dispatchEvent(new Event('change',{bubbles:true}))",[b64])
    waitjs("document.getElementById('redactPageLabel').textContent.includes('2')")
    js("""const st=document.getElementById('redactStage'),r=st.getBoundingClientRect();
    const ev=(t,x,y,b)=>new PointerEvent(t,{clientX:r.left+r.width*x,clientY:r.top+r.height*y,bubbles:true,cancelable:true,pointerId:1,pointerType:'mouse',isPrimary:true,button:0,buttons:b});
    st.dispatchEvent(ev('pointerdown',.05,.44,1));
    window.dispatchEvent(ev('pointermove',.95,.62,1));
    window.dispatchEvent(ev('pointerup',.95,.62,0));""")
    waitjs("document.querySelectorAll('.redact-box').length===1")
    time.sleep(.6)
    png=call('GET','/screenshot')
    # convert PNG -> small JPEG in-page via canvas
    jpg=asyncjs("""const done=arguments[arguments.length-1],b=atob(arguments[0]);
    let s='';const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    const bytes=new Uint8Array(b.length);for(let i=0;i<b.length;i++)bytes[i]=b.charCodeAt(i);
    const img=new Image();img.onload=()=>{
      const scale=Math.min(1,1280/img.width);
      const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);
      c.getContext('2d').drawImage(img,0,0,c.width,c.height);
      c.toBlob(bl=>{const fr=new FileReader();fr.onload=()=>done(String(fr.result).split(',')[1]);fr.readAsDataURL(bl)},'image/jpeg',.72)
    };img.src='data:image/png;base64,'+arguments[0]""",[png])
    open('/tmp/opencode/final-redact.jpg','wb').write(base64.b64decode(jpg))
    print('saved final-redact.jpg', len(jpg))
finally:
    try: req('DELETE',root)
    except Exception: pass

