import json, urllib.request, time, base64
BASE='http://127.0.0.1:9515'
def req(method,path,data=None):
    body=None if data is None else json.dumps(data).encode()
    r=urllib.request.Request(BASE+path,data=body,headers={'Content-Type':'application/json'},method=method)
    with urllib.request.urlopen(r,timeout=90) as x: return json.loads(x.read() or b'{}')
opts={'capabilities':{'alwaysMatch':{'browserName':'chrome','goog:chromeOptions':{'args':['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--window-size=1240,860','--hide-scrollbars']}}}}
sid=req('POST','/session',opts)['value']['sessionId']; root='/session/'+sid
def call(method,path,data=None):
    v=req(method,root+path,data); val=v.get('value')
    if isinstance(val,dict) and val.get('error'): raise RuntimeError(val)
    return val
def js(script,args=[]): return call('POST','/execute/sync',{'script':script,'args':args})
def asyncjs(script,args=[]): return call('POST','/execute/async',{'script':script,'args':args})
def waitjs(expr,timeout=60):
    end=time.time()+timeout
    while time.time()<end:
        if js('return '+expr): return True
        time.sleep(.2)
    raise TimeoutError(expr)
results={'pass':[],'fail':[]}
def check(name,ok,info=''):
    results['pass' if ok else 'fail'].append(name)
    print(('PASS' if ok else 'FAIL'),name,('' if ok else info))
try:
    call('POST','/url',{'url':'http://127.0.0.1:8765/'})
    waitjs("document.readyState==='complete'")
    js("window.__errors=[];window.addEventListener('error',e=>window.__errors.push(String(e.message||e)));window.addEventListener('unhandledrejection',e=>window.__errors.push('rej:'+String(e.reason)))")
    js("window.__captures=[];const oldURL=URL.createObjectURL.bind(URL);URL.createObjectURL=b=>{const e={blob:b,name:null};window.__captures.push(e);return oldURL(b)};const oldClick=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){if(this.download&&window.__captures.length)window.__captures[window.__captures.length-1].name=this.download;return oldClick.call(this)}")
    check('flatten card listed', 'flatten' in js("return [...document.querySelectorAll('[data-tool]')].map(b=>b.dataset.tool)"))
    js("document.querySelector(`[data-tool='flatten']`).click()")
    waitjs("document.getElementById('toolModal').classList.contains('open')")
    check('flatten modal title', js("return document.getElementById('modalTitle').textContent")=='Flatten PDF')
    check('flatten quality chips', js("return document.querySelectorAll('input[name=flattenQuality]').length")==2)
    b64=base64.b64encode(open('/tmp/opencode/secret.pdf','rb').read()).decode()
    js("const b=atob(arguments[0]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);const dt=new DataTransfer();dt.items.add(new File([u],'secret.pdf',{type:'application/pdf'}));const el=document.getElementById('fileInput');el.files=dt.files;el.dispatchEvent(new Event('change',{bubbles:true}))",[b64])
    waitjs("document.querySelectorAll('#fileRows .file-row').length===1")
    # take screenshot before applying
    png=call('GET','/screenshot')
    jpg=asyncjs("""const done=arguments[arguments.length-1];const b=atob(arguments[0]);
    const bytes=new Uint8Array(b.length);for(let i=0;i<b.length;i++)bytes[i]=b.charCodeAt(i);
    const img=new Image();img.onload=()=>{const s=Math.min(1,1280/img.width);const c=document.createElement('canvas');c.width=Math.round(img.width*s);c.height=Math.round(img.height*s);c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(bl=>{const fr=new FileReader();fr.onload=()=>done(String(fr.result).split(',')[1]);fr.readAsDataURL(bl)},'image/jpeg',.72)};img.src='data:image/png;base64,'+arguments[0]""",[png])
    open('/tmp/opencode/final-flatten.jpg','wb').write(base64.b64decode(jpg))
    before=js('return window.__captures.length')
    js("document.getElementById('modalAction').click()")
    waitjs("!document.getElementById('modalAction').classList.contains('loading')",90)
    err=js("return (document.getElementById('modalError').classList.contains('show')?document.getElementById('modalError').textContent:'')")
    got=js('return window.__captures.length')>before
    check('flatten applies without error', got and err=='', err)
    check('flatten output filename', js("return window.__captures[window.__captures.length-1].name")=='secret-flat.pdf')
    # save output and verify deep in-browser
    data=asyncjs("const done=arguments[arguments.length-1];const c=window.__captures[arguments[0]];const r=new FileReader();r.onload=()=>done(String(r.result).split(',')[1]);r.readAsDataURL(c.blob)",[before])
    open('/tmp/opencode/flat.pdf','wb').write(base64.b64decode(data))
    v=asyncjs("""const done=arguments[arguments.length-1],b=atob(arguments[0]),u=new Uint8Array(b.length);
    for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
    (async()=>{
      const copy=u.slice();
      const pdf=await pdfjsLib.getDocument({data:u}).promise;
      const texts=[];
      for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i);const tc=await p.getTextContent();texts.push(tc.items.map(t=>t.str).join(' ').trim())}
      const sizes=[];
      for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i);const vp=p.getViewport({scale:1});sizes.push(Math.round(vp.width)+'x'+Math.round(vp.height))}
      pdf.destroy();
      const out=await PDFLib.PDFDocument.load(copy);
      const xo=[];
      for(let i=0;i<out.getPageCount();i++){const e=out.getPage(i).node.normalizedEntries().XObject;xo.push(e?Object.keys(e).length:0)}
      const annots=out.getPages().map(p=>String(p.node.get(PDFLib.PDFName.of('Annots'))||''));
      done({pages:out.getPageCount(),texts,sizes,xo,annots});
    })().catch(e=>done({error:String(e)}))""",[base64.b64encode(open('/tmp/opencode/flat.pdf','rb').read()).decode()])
    check('flatten 2 pages', v.get('pages')==2, v)
    check('flatten no text layer', all(t=='' for t in v.get('texts',[None])), v.get('texts'))
    check('flatten page size preserved', v.get('sizes')==['420x560','420x560'], v.get('sizes'))
    check('flatten pages are images', all(x>0 for x in v.get('xo',[])), v.get('xo'))
    errs=js("return window.__errors.splice(0)")
    check('no js errors', errs==[], errs)
finally:
    try: req('DELETE',root)
    except Exception: pass
