const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
const { PDFDocument } = require('./vendor/pdf-lib.min.js');
const source = fs.readFileSync('app.js', 'utf8');
function snippet(start, end) {
  const a = source.indexOf(`function ${start}(`);
  const b = source.indexOf(`function ${end}(`, a);
  assert.notEqual(a, -1, `missing ${start}`);
  assert.notEqual(b, -1, `missing ${end}`);
  return source.slice(a, b);
}
const context = vm.createContext({
  selectedFiles: [{}],
  splitState: {mode:'table', rows:[], manual:'', selected:new Set(), total:3},
});
vm.runInContext([
  snippet('rangeText','slugRange'),
  snippet('slugRange','handleSplitInput'),
  snippet('selectionRanges','handleSplitClick'),
  snippet('currentSplitRanges','renderSplitSummary'),
  snippet('parsePages','readPDF'),
].join('\n'), context);
const { currentSplitRanges, parsePages } = context;
(async () => {
  const sourceDoc = await PDFDocument.create();
  for (const size of [100, 200, 300]) sourceDoc.addPage([size, size]);
  async function sizes(ids) {
    const out = await PDFDocument.create();
    const pages = await out.copyPages(sourceDoc, ids);
    pages.forEach(page => out.addPage(page));
    return out.getPages().map(page => page.getWidth());
  }
  context.splitState.mode = 'table';
  context.splitState.rows = [{start:'1',end:'1'}];
  let ranges = currentSplitRanges();
  assert.deepEqual(Array.from(ranges[0].ids), [0]);
  assert.deepEqual(await sizes(ranges[0].ids), [100]);
  context.splitState.rows = [{start:'2',end:'3'}];
  ranges = currentSplitRanges();
  assert.deepEqual(Array.from(ranges[0].ids), [1,2]);
  assert.deepEqual(await sizes(ranges[0].ids), [200,300]);
  context.splitState.mode = 'picker';
  context.splitState.selected = new Set([1,3]);
  ranges = currentSplitRanges();
  assert.deepEqual(ranges.map(r => Array.from(r.ids)), [[0],[2]]);
  assert.deepEqual(await sizes(ranges[0].ids), [100]);
  assert.deepEqual(await sizes(ranges[1].ids), [300]);
  assert.deepEqual(Array.from(parsePages('1-2, 3', 3)), [0,1,2]);
  assert.deepEqual(Array.from(parsePages('3, 1', 3)), [2,0]);
  assert.throws(() => { context.splitState.mode='table'; context.splitState.rows=[{start:'1.5',end:'2'}]; currentSplitRanges(); }, /angka bulat/);
  console.log('PASS: split table, picker, and extract page indices match requested pages; decimals rejected.');
})().catch(error => { console.error(error); process.exitCode = 1; });
