217: 
218: <!-- examples/progress.mjs -->
219: ```js
220: import { createQpdf } from "@mssio/qpdf-wasm";
221: 
222: // `bar` is a <progress> element.
223: export async function compressWithProgressBar(file, bar) {
224:   const qpdf = await createQpdf();
225:   try {
226:     bar.removeAttribute("value"); // indeterminate until qpdf starts writing
227:     const { output } = await qpdf.compress(file, {
228:       onProgress: (percent) => {
229:         bar.max = 100;
230:         bar.value = percent;
231:       },
232:     });
233:     return output;
